# -*- coding: utf-8 -*-
# Book summary (one A4 page) in 9 languages — second edition (fusions, Signature, 24 painters, 14 chapters).
T = {}
T['EN'] = dict(sub='The Book of Golden Music — a summary', sub2='On finding beauty between tone and colour · RafFel',
 intro='The book tells the story of a desire two and a half thousand years old: to join what we hear with what we see. Pythagoras at his string, Newton over the prism, Castel at his colour harpsichord, Scriabin with his keyboard of light, Disney in Fantasia, David Byrne today — different hands, different centuries, the same dream. Paintiano is the instrument in which that dream can, for the first time, be held in your hand.',
 secs=[('Tone and colour are the same wave','Concert A — 440 hertz — raised by forty octaves becomes a warm red. Sound is a wave in the air, light a wave in the field; they are only forty doublings apart. The whole system stands on this bridge: hue carries the pitch, octave carries the lightness, the force of the keystroke carries the saturation. A bass C2 is dark blue, a soprano C7 almost white; forte is saturated, pianissimo barely a shadow.'),
 ('Four views of one wheel','Twelve tones can be laid onto the colour wheel by four rules: Harmony (the circle of fifths — the musician’s view), Spectrum (the chromatic rainbow — the physicist’s view), Kontra (complementary intervals — the painter’s view) and φ (the golden angle of 137.5° — nature’s view). A fifth view, Custom, waits for your own map. There is no single right answer — there are four true ones.'),
 ('It lives in all of us','Synaesthetes have always seen music — and science shows that a piece of the synaesthete sits in each of us: high tones bright, low tones dark, sharp sounds sharp shapes (bouba and kiki). When you say “dark music”, you are not speaking in metaphor. That is why little Lara at the piano paints her sadness blue without anyone having taught her.'),
 ('A picture that plays','The rule can be turned around: if a tone can become a colour, a colour can become a tone. Load a photograph, Guernica or a child’s drawing — and Paintiano plays it. There and back, without loss. And the picture has more than one voice: it can be played in the spirit of Chopin, Satie or Bach — twelve composers, each reading it differently.'),
 ('When painters meet','The same piece can be seen through twenty-four pairs of eyes: in the spirit of Picasso the shapes break, of Pollock the paint falls, of Kusama it turns to dots, of Klimt it glows in gold. And the painters can meet — two to five of them cross into a single new hand that belongs to none, yet in which you recognise each. The rule comes from the music itself: rhythm builds the structure, melody leads the gesture, harmony pours the field, brightness lays the ornament, register gives the light. With the Signature, the piece chooses its painters itself. Every view is true, because beneath them all runs the same deterministic mathematics: the same song, the same painting, every time.')],
 quote=['“Music has colour. It always had.','We simply forgot.”'], foot='The whole book — fourteen chapters — is in the app, on its own or with Pro and Pro AI')
T['SK'] = dict(sub='Kniha o zlatej hudbe — zhrnutie', sub2='O hľadaní krásy medzi tónom a farbou · RafFel',
 intro='Kniha rozpráva príbeh jednej dvaapoltisícročnej túžby: spojiť to, čo počujeme, s tým, čo vidíme. Pytagoras pri strune, Newton nad hranolom, Castel pri farebnom čembale, Skriabin s klávesnicou svetla, Disney vo Fantasii, dnes David Byrne — rôzne ruky, rôzne storočia, rovnaký sen. Paintiano je nástroj, v ktorom sa ten sen dá prvý raz držať v ruke.',
 secs=[('Tón a farba sú tá istá vlna','Komorné a — 440 hertzov — zdvihnuté o štyridsať oktáv sa stane teplou červenou. Zvuk je vlnenie vzduchu, svetlo vlnenie poľa; delí ich len štyridsať zdvojení. Na tomto moste stojí celý systém: odtieň nesie výšku tónu, oktáva svetlosť, sila úderu sýtosť. Basové C2 je tmavomodré, sopránové C7 takmer biele; forte je sýte, pianissimo sotva tieň.'),
 ('Štyri pohľady na jedno koleso','Dvanásť tónov sa dá na farebné koleso položiť štyrmi pravidlami: Harmónia (kruh kvínt — pohľad hudobníka), Spektrum (chromatická dúha — pohľad fyzika), Kontra (komplementárne intervaly — pohľad maliara) a φ (zlatý uhol 137,5° — pohľad prírody). Piaty pohľad, Vlastný, čaká na tvoju mapu. Nie je jedna správna odpoveď — sú štyri pravdivé.'),
 ('Máme to v sebe','Synestetici vidia hudbu odjakživa — a veda ukazuje, že kúsok synestetika sedí v každom z nás: vysoké tóny svetlé, nízke tmavé, ostré zvuky ostré tvary (bouba a kiki). Keď povieš „temná hudba“, nehovoríš metaforu. Preto malá Lara pri klavíri maľuje smútok domodra bez toho, aby ju to ktokoľvek učil.'),
 ('Obraz, ktorý hrá','Pravidlo sa dá otočiť: ak vieš z tónu spraviť farbu, vieš z farby spraviť tón. Načítaš fotku, Guernicu či detskú kresbu — a Paintiano ju zahrá. Tam aj späť, bez straty. A obraz má viac než jeden hlas: dá sa zahrať v duchu Chopina, Satieho či Bacha — dvanásť skladateľov, každý ho číta inak.'),
 ('Keď sa maliari stretnú','Tá istá skladba sa dá uvidieť dvadsiatimi štyrmi pármi očí: v duchu Picassa sa tvary lámu, v duchu Pollocka farba padá, u Kusamy sa mení na bodky, u Klimta žiari zlatom. A maliari sa môžu stretnúť — dvaja až piati sa skrížia do jedného nového rukopisu, ktorý nepatrí nikomu z nich, a predsa v ňom spoznáš každého. Pravidlo dáva sama hudba: rytmus stavia štruktúru, melódia vedie gesto, harmónia leje pole, jas kladie ornament, register dáva svetlo. So Signatúrou si skladba vyberie maliarov sama. Každý pohľad je pravdivý, lebo pod všetkými beží tá istá deterministická matematika: tá istá pieseň, tá istá maľba, zakaždým.')],
 quote=['„Hudba má farbu. Vždy mala.','My sme to len zabudli.“'], foot='Celá kniha — štrnásť kapitol — je v appke, samostatne alebo v cene Pro a Pro AI')
T['DE'] = dict(sub='Das Buch der goldenen Musik — Zusammenfassung', sub2='Von der Suche nach Schönheit zwischen Ton und Farbe · RafFel',
 intro='Das Buch erzählt die Geschichte einer zweieinhalbtausend Jahre alten Sehnsucht: das Gehörte mit dem Gesehenen zu verbinden. Pythagoras an der Saite, Newton über dem Prisma, Castel am Farbcembalo, Skrjabin mit seiner Lichtklaviatur, Disney in Fantasia, heute David Byrne — verschiedene Hände, verschiedene Jahrhunderte, derselbe Traum. Paintiano ist das Instrument, in dem sich dieser Traum zum ersten Mal in der Hand halten lässt.',
 secs=[('Ton und Farbe sind dieselbe Welle','Der Kammerton a — 440 Hertz — wird, um vierzig Oktaven angehoben, zu einem warmen Rot. Klang ist eine Welle der Luft, Licht eine Welle des Feldes; nur vierzig Verdopplungen liegen dazwischen. Auf dieser Brücke steht das ganze System: der Farbton trägt die Tonhöhe, die Oktave die Helligkeit, die Anschlagsstärke die Sättigung. Ein Bass-C2 ist dunkelblau, ein Sopran-C7 fast weiß; Forte ist satt, Pianissimo kaum ein Schatten.'),
 ('Vier Blicke auf ein Rad','Zwölf Töne lassen sich nach vier Regeln auf den Farbkreis legen: Harmonie (Quintenzirkel — der Blick des Musikers), Spektrum (chromatischer Regenbogen — der Blick des Physikers), Kontra (Komplementärintervalle — der Blick des Malers) und φ (der goldene Winkel von 137,5° — der Blick der Natur). Ein fünfter Blick, Eigen, wartet auf deine eigene Karte. Es gibt nicht die eine richtige Antwort — es gibt vier wahre.'),
 ('Es steckt in uns allen','Synästheten haben Musik schon immer gesehen — und die Wissenschaft zeigt: ein Stück Synästhet sitzt in jedem von uns. Hohe Töne hell, tiefe dunkel, scharfe Klänge scharfe Formen (Bouba und Kiki). Wer „dunkle Musik“ sagt, spricht nicht in Metaphern. Darum malt die kleine Lara am Klavier ihre Traurigkeit blau, ohne dass es ihr jemand beigebracht hätte.'),
 ('Ein Bild, das spielt','Die Regel lässt sich umkehren: Wird aus einem Ton eine Farbe, wird aus einer Farbe ein Ton. Lade ein Foto, Guernica oder eine Kinderzeichnung — und Paintiano spielt es. Hin und zurück, ohne Verlust. Und das Bild hat mehr als eine Stimme: Es lässt sich im Geist von Chopin, Satie oder Bach spielen — zwölf Komponisten, jeder liest es anders.'),
 ('Wenn Maler sich begegnen','Dasselbe Stück lässt sich mit vierundzwanzig Augenpaaren sehen: Im Geist Picassos brechen die Formen, bei Pollock fällt die Farbe, bei Kusama wird sie zu Punkten, bei Klimt glüht sie in Gold. Und die Maler können sich begegnen — zwei bis fünf verschmelzen zu einer einzigen neuen Handschrift, die keinem von ihnen gehört und in der man doch jeden erkennt. Die Regel gibt die Musik selbst: Der Rhythmus baut die Struktur, die Melodie führt die Geste, die Harmonie gießt das Feld, die Helligkeit legt das Ornament, das Register gibt das Licht. Mit der Signatur wählt das Stück seine Maler selbst. Jeder Blick ist wahr, denn unter allen läuft dieselbe deterministische Mathematik: dasselbe Lied, dasselbe Bild, jedes Mal.')],
 quote=['„Musik hat Farbe. Schon immer.','Wir haben es nur vergessen.“'], foot='Das ganze Buch — vierzehn Kapitel — in der App, einzeln oder in Pro und Pro AI inklusive')
T['FR'] = dict(sub='Le Livre de la musique dorée — résumé', sub2='À la recherche de la beauté entre le son et la couleur · RafFel',
 intro='Ce livre raconte l’histoire d’un désir vieux de deux mille cinq cents ans : unir ce que nous entendons à ce que nous voyons. Pythagore à sa corde, Newton devant le prisme, Castel à son clavecin oculaire, Scriabine et son clavier de lumière, Disney dans Fantasia, David Byrne aujourd’hui — des mains différentes, des siècles différents, le même rêve. Paintiano est l’instrument où, pour la première fois, ce rêve tient dans la main.',
 secs=[('Le son et la couleur sont la même onde','Le la du diapason — 440 hertz — élevé de quarante octaves devient un rouge chaud. Le son est une onde de l’air, la lumière une onde du champ ; quarante doublements seulement les séparent. Tout le système repose sur ce pont : la teinte porte la hauteur, l’octave la clarté, la force de la frappe la saturation. Un do2 grave est bleu sombre, un do7 de soprano presque blanc ; le forte est saturé, le pianissimo à peine une ombre.'),
 ('Quatre regards sur une même roue','Douze tons peuvent se poser sur la roue des couleurs selon quatre règles : Harmonie (le cycle des quintes — le regard du musicien), Spectre (l’arc-en-ciel chromatique — le regard du physicien), Kontra (les intervalles complémentaires — le regard du peintre) et φ (l’angle d’or de 137,5° — le regard de la nature). Un cinquième regard, Personnel, attend ta propre carte. Il n’y a pas une seule bonne réponse — il y en a quatre vraies.'),
 ('Nous l’avons en nous','Les synesthètes ont toujours vu la musique — et la science montre qu’un morceau de synesthète sommeille en chacun de nous : les sons aigus clairs, les graves sombres, les sons pointus aux formes pointues (bouba et kiki). Dire « musique sombre », ce n’est pas une métaphore. C’est pourquoi la petite Lara, au piano, peint sa tristesse en bleu sans que personne le lui ait appris.'),
 ('Une image qui joue','La règle se retourne : si un ton peut devenir couleur, une couleur peut devenir ton. Charge une photo, Guernica ou un dessin d’enfant — et Paintiano le joue. Aller et retour, sans perte. Et l’image a plus d’une voix : elle peut se jouer dans l’esprit de Chopin, de Satie ou de Bach — douze compositeurs, chacun la lit autrement.'),
 ('Quand les peintres se rencontrent','La même œuvre peut se voir par vingt-quatre paires d’yeux : dans l’esprit de Picasso les formes se brisent, chez Pollock la peinture tombe, chez Kusama elle devient points, chez Klimt elle rayonne d’or. Et les peintres peuvent se rencontrer — deux à cinq se fondent en une seule main nouvelle, qui n’appartient à aucun d’eux et où l’on reconnaît pourtant chacun. La règle vient de la musique elle-même : le rythme bâtit la structure, la mélodie mène le geste, l’harmonie verse le champ, l’éclat pose l’ornement, le registre donne la lumière. Avec la Signature, l’œuvre choisit elle-même ses peintres. Chaque regard est vrai, car sous chacun court la même mathématique déterministe : la même chanson, la même peinture, à chaque fois.')],
 quote=['« La musique a une couleur. Depuis toujours.','Nous l’avions simplement oublié. »'], foot='Le livre entier — quatorze chapitres — dans l’app, seul ou inclus dans Pro et Pro AI')
T['ES'] = dict(sub='El libro de la música dorada — resumen', sub2='Sobre la búsqueda de la belleza entre el tono y el color · RafFel',
 intro='El libro cuenta la historia de un deseo de dos mil quinientos años: unir lo que oímos con lo que vemos. Pitágoras ante su cuerda, Newton sobre el prisma, Castel en su clavecín ocular, Scriabin con su teclado de luz, Disney en Fantasía, hoy David Byrne — distintas manos, distintos siglos, el mismo sueño. Paintiano es el instrumento en el que ese sueño, por primera vez, cabe en la mano.',
 secs=[('El tono y el color son la misma onda','El la de concierto — 440 hercios — elevado cuarenta octavas se convierte en un rojo cálido. El sonido es una onda del aire, la luz una onda del campo; solo cuarenta duplicaciones las separan. Todo el sistema se apoya en ese puente: el matiz lleva la altura, la octava la luminosidad, la fuerza de la pulsación la saturación. Un do2 grave es azul oscuro, un do7 de soprano casi blanco; el forte es saturado, el pianissimo apenas una sombra.'),
 ('Cuatro miradas sobre una misma rueda','Doce tonos pueden colocarse sobre la rueda del color según cuatro reglas: Armonía (el círculo de quintas — la mirada del músico), Espectro (el arcoíris cromático — la mirada del físico), Kontra (los intervalos complementarios — la mirada del pintor) y φ (el ángulo áureo de 137,5° — la mirada de la naturaleza). Una quinta mirada, Propia, espera tu propio mapa. No hay una única respuesta correcta — hay cuatro verdaderas.'),
 ('Lo llevamos dentro','Los sinestésicos siempre han visto la música — y la ciencia muestra que un pedazo de sinestésico vive en cada uno de nosotros: tonos agudos claros, graves oscuros, sonidos afilados con formas afiladas (bouba y kiki). Decir «música oscura» no es una metáfora. Por eso la pequeña Lara, al piano, pinta su tristeza de azul sin que nadie se lo haya enseñado.'),
 ('Una imagen que suena','La regla se puede invertir: si un tono puede volverse color, un color puede volverse tono. Carga una foto, el Guernica o un dibujo infantil — y Paintiano lo toca. Ida y vuelta, sin pérdida. Y la imagen tiene más de una voz: puede tocarse en el espíritu de Chopin, Satie o Bach — doce compositores, cada uno la lee a su manera.'),
 ('Cuando los pintores se encuentran','La misma pieza puede verse con veinticuatro pares de ojos: en el espíritu de Picasso las formas se quiebran, con Pollock la pintura cae, con Kusama se vuelve puntos, con Klimt brilla en oro. Y los pintores pueden encontrarse — de dos a cinco se funden en una sola mano nueva, que no es de ninguno y en la que, sin embargo, reconoces a cada uno. La regla la da la propia música: el ritmo construye la estructura, la melodía guía el gesto, la armonía vierte el campo, el brillo pone el ornamento, el registro da la luz. Con la Firma, la pieza elige ella misma a sus pintores. Cada mirada es verdadera, porque bajo todas corre la misma matemática determinista: la misma canción, la misma pintura, cada vez.')],
 quote=['«La música tiene color. Siempre lo tuvo.','Solo lo habíamos olvidado.»'], foot='El libro completo — catorce capítulos — en la app, solo o incluido en Pro y Pro AI')
T['PT'] = dict(sub='O livro da música dourada — resumo', sub2='Sobre a busca da beleza entre o tom e a cor · RafFel',
 intro='O livro conta a história de um desejo com dois mil e quinhentos anos: unir o que ouvimos ao que vemos. Pitágoras junto à corda, Newton sobre o prisma, Castel no seu cravo ocular, Scriabin com o seu teclado de luz, Disney em Fantasia, hoje David Byrne — mãos diferentes, séculos diferentes, o mesmo sonho. O Paintiano é o instrumento em que esse sonho, pela primeira vez, cabe na mão.',
 secs=[('O tom e a cor são a mesma onda','O lá de concerto — 440 hertz — elevado quarenta oitavas torna-se um vermelho quente. O som é uma onda do ar, a luz uma onda do campo; apenas quarenta duplicações as separam. Todo o sistema assenta nessa ponte: o matiz carrega a altura, a oitava a luminosidade, a força do toque a saturação. Um dó2 grave é azul-escuro, um dó7 de soprano quase branco; o forte é saturado, o pianissimo mal é uma sombra.'),
 ('Quatro olhares sobre a mesma roda','Doze tons podem pousar na roda das cores segundo quatro regras: Harmonia (o círculo de quintas — o olhar do músico), Espectro (o arco-íris cromático — o olhar do físico), Kontra (os intervalos complementares — o olhar do pintor) e φ (o ângulo de ouro de 137,5° — o olhar da natureza). Um quinto olhar, Próprio, espera pelo teu próprio mapa. Não há uma única resposta certa — há quatro verdadeiras.'),
 ('Trazemo-lo dentro de nós','Os sinestésicos sempre viram a música — e a ciência mostra que um pedaço de sinestésico mora em cada um de nós: tons agudos claros, graves escuros, sons afiados com formas afiadas (bouba e kiki). Dizer «música sombria» não é metáfora. Por isso a pequena Lara, ao piano, pinta a sua tristeza de azul sem que ninguém lho tenha ensinado.'),
 ('Uma imagem que toca','A regra pode inverter-se: se um tom pode tornar-se cor, uma cor pode tornar-se tom. Carrega uma foto, a Guernica ou um desenho de criança — e o Paintiano toca-o. Ida e volta, sem perda. E a imagem tem mais de uma voz: pode tocar-se no espírito de Chopin, Satie ou Bach — doze compositores, cada um lê-a à sua maneira.'),
 ('Quando os pintores se encontram','A mesma peça pode ver-se com vinte e quatro pares de olhos: no espírito de Picasso as formas quebram-se, com Pollock a tinta cai, com Kusama torna-se pontos, com Klimt brilha em ouro. E os pintores podem encontrar-se — dois a cinco fundem-se numa única mão nova, que não é de nenhum deles e na qual, ainda assim, reconheces cada um. A regra vem da própria música: o ritmo constrói a estrutura, a melodia conduz o gesto, a harmonia verte o campo, o brilho pousa o ornamento, o registo dá a luz. Com a Assinatura, a peça escolhe ela própria os seus pintores. Cada olhar é verdadeiro, porque sob todos corre a mesma matemática determinista: a mesma canção, a mesma pintura, de cada vez.')],
 quote=['«A música tem cor. Sempre teve.','Nós apenas o esquecemos.»'], foot='O livro completo — catorze capítulos — na app, sozinho ou incluído no Pro e no Pro AI')
T['zh'] = dict(sub='金色音乐之书 · 摘要', sub2='在音与色之间寻找美 · RafFel',
 intro='这本书讲述一个绵延两千五百年的渴望：把听见的与看见的连在一起。毕达哥拉斯拨动琴弦，牛顿俯身棱镜，卡斯特尔造出色彩羽管键琴，斯克里亚宾设想光之键盘，迪士尼拍出《幻想曲》，今天还有大卫·伯恩——不同的手，不同的世纪，同一个梦。Paintiano 是让这个梦第一次可以握在手中的乐器。',
 secs=[('音与色是同一种波','标准音 a — 440 赫兹——升高四十个八度，便成为温暖的红色。声音是空气的波，光是场的波；相隔的只是四十次倍频。整个系统建立在这座桥上：色相承载音高，八度承载明度，触键力度承载饱和度。低音 C2 是深蓝，高音 C7 近乎纯白；强奏饱满，弱奏只剩一抹影子。'),
 ('同一个色轮的四种目光','十二个音可以按四条规则落在色轮上：和声（五度圈——音乐家的目光）、光谱（半音彩虹——物理学家的目光）、对位（互补音程——画家的目光）、φ（137.5° 黄金角——自然的目光）。第五种目光“自定义”，等待你画出自己的地图。没有唯一的正确答案——有四个真实的答案。'),
 ('它就在我们身上','联觉者从来都看得见音乐——科学表明，每个人身上都住着一小块联觉者：高音明亮，低音深沉，尖锐的声音对应尖锐的形状（bouba 与 kiki）。当你说“黑暗的音乐”，那不是比喻。所以小拉拉在钢琴前把悲伤画成蓝色，没有任何人教过她。'),
 ('会演奏的画','规则可以倒转：音能变成色，色也能变成音。载入一张照片、《格尔尼卡》或孩子的涂鸦——Paintiano 会把它演奏出来。来回往返，毫无损耗。一幅画还不止一种声音：它可以用肖邦、萨蒂或巴赫的精神来演奏——十二位作曲家，各有各的读法。'),
 ('当画家相遇','同一首曲子能被二十四双眼睛看见：以毕加索的精神，形状折断；以波洛克的精神，颜料坠落；在草间弥生那里化为圆点；在克里姆特那里闪耀金光。画家还可以相遇——两位到五位融合成一只全新的手，它不属于其中任何一位，你却能认出每一位。规则来自音乐本身：节奏搭建结构，旋律引领笔势，和声铺开色域，明亮点缀装饰，音区赋予光。有了“签名”，曲子会自己挑选画家。每一种目光都真实，因为在一切之下运转的，是同一套确定性的数学：同一首歌，同一幅画，每一次都相同。')],
 quote=['“音乐有颜色。一直都有。','只是我们忘了。”'], foot='整本书 · 十四章 · 在 App 里，可单独购买，也包含在 Pro 与 Pro AI 中')
T['zhTW'] = dict(sub='金色音樂之書 · 摘要', sub2='在音與色之間尋找美 · RafFel',
 intro='這本書講述一個綿延兩千五百年的渴望：把聽見的與看見的連在一起。畢達哥拉斯撥動琴弦，牛頓俯身稜鏡，卡斯特爾造出色彩羽管鍵琴，斯克里亞賓設想光之鍵盤，迪士尼拍出《幻想曲》，今天還有大衛·伯恩——不同的手，不同的世紀，同一個夢。Paintiano 是讓這個夢第一次可以握在手中的樂器。',
 secs=[('音與色是同一種波','標準音 a — 440 赫茲——升高四十個八度，便成為溫暖的紅色。聲音是空氣的波，光是場的波；相隔的只是四十次倍頻。整個系統建立在這座橋上：色相承載音高，八度承載明度，觸鍵力度承載飽和度。低音 C2 是深藍，高音 C7 近乎純白；強奏飽滿，弱奏只剩一抹影子。'),
 ('同一個色輪的四種目光','十二個音可以按四條規則落在色輪上：和聲（五度圈——音樂家的目光）、光譜（半音彩虹——物理學家的目光）、對位（互補音程——畫家的目光）、φ（137.5° 黃金角——自然的目光）。第五種目光「自訂」，等待你畫出自己的地圖。沒有唯一的正確答案——有四個真實的答案。'),
 ('它就在我們身上','聯覺者從來都看得見音樂——科學表明，每個人身上都住著一小塊聯覺者：高音明亮，低音深沉，尖銳的聲音對應尖銳的形狀（bouba 與 kiki）。當你說「黑暗的音樂」，那不是比喻。所以小拉拉在鋼琴前把悲傷畫成藍色，沒有任何人教過她。'),
 ('會演奏的畫','規則可以倒轉：音能變成色，色也能變成音。載入一張照片、《格爾尼卡》或孩子的塗鴉——Paintiano 會把它演奏出來。來回往返，毫無損耗。一幅畫還不止一種聲音：它可以用蕭邦、薩提或巴赫的精神來演奏——十二位作曲家，各有各的讀法。'),
 ('當畫家相遇','同一首曲子能被二十四雙眼睛看見：以畢加索的精神，形狀折斷；以波洛克的精神，顏料墜落；在草間彌生那裡化為圓點；在克林姆那裡閃耀金光。畫家還可以相遇——兩位到五位融合成一隻全新的手，它不屬於其中任何一位，你卻能認出每一位。規則來自音樂本身：節奏搭建結構，旋律引領筆勢，和聲鋪開色域，明亮點綴裝飾，音區賦予光。有了「簽名」，曲子會自己挑選畫家。每一種目光都真實，因為在一切之下運轉的，是同一套確定性的數學：同一首歌，同一幅畫，每一次都相同。')],
 quote=['「音樂有顏色。一直都有。','只是我們忘了。」'], foot='整本書 · 十四章 · 在 App 裡，可單獨購買，也包含在 Pro 與 Pro AI 中')
T['ja'] = dict(sub='黄金の音楽の本 · 要約', sub2='音と色のあいだに美を求めて · RafFel',
 intro='この本は、二千五百年つづく一つの憧れの物語を語る。聞こえるものと見えるものを結びつけたい——ピタゴラスは弦のそばで、ニュートンはプリズムの上で、カステルは色彩チェンバロで、スクリャービンは光の鍵盤で、ディズニーは『ファンタジア』で、そして今日はデヴィッド・バーンが。手も世紀も違えど、夢は同じ。Paintiano は、その夢をはじめて手のひらに載せられる楽器である。',
 secs=[('音と色は同じ波','コンサートピッチの a — 440 ヘルツ——を四十オクターブ上げると、温かな赤になる。音は空気の波、光は場の波。隔てるのは四十回の倍化だけだ。システム全体はこの橋の上に立つ。色相が音高を、オクターブが明るさを、打鍵の強さが彩度を運ぶ。低音の C2 は深い青、高音の C7 はほとんど白。フォルテは鮮やかに、ピアニッシモは影のように。'),
 ('一つの色環への四つのまなざし','十二の音は四つの規則で色環に置ける。ハーモニー（五度圏——音楽家のまなざし）、スペクトル（半音の虹——物理学者のまなざし）、コントラ（補色音程——画家のまなざし）、そして φ（137.5° の黄金角——自然のまなざし）。五つ目の「カスタム」は、あなた自身の地図を待っている。唯一の正解はない——四つの真実があるのだ。'),
 ('私たちの中にある','共感覚者はいつも音楽を見てきた。そして科学は、誰の中にも小さな共感覚者が住むことを示す。高い音は明るく、低い音は暗く、鋭い音は鋭い形（bouba と kiki）。「暗い音楽」という言葉は比喩ではない。だから小さなララはピアノの前で、誰に教わることもなく、悲しみを青く塗る。'),
 ('奏でる絵','規則は裏返せる。音が色になるなら、色は音になる。写真を、ゲルニカを、子どもの落書きを読み込めば——Paintiano がそれを奏でる。行きも帰りも、失われるものはない。そして絵の声は一つではない。ショパン、サティ、バッハの精神で奏でられる——十二人の作曲家が、それぞれ違う読み方をする。'),
 ('画家たちが出会うとき','同じ曲は二十四組の目で見ることができる。ピカソの精神では形が砕け、ポロックでは絵具が落ち、草間では水玉になり、クリムトでは金に輝く。そして画家たちは出会える——二人から五人が、誰のものでもなく、それでいて一人ひとりが見てとれる、一つの新しい手に溶け合う。規則は音楽そのものがくれる。リズムが構造を建て、旋律が身ぶりを導き、和声が色面を流し、明るさが装飾を置き、音域が光を与える。「署名」なら、曲が自分で画家を選ぶ。どのまなざしも真実だ。すべての下を流れるのは同じ決定論的な数学。同じ歌、同じ絵、毎回必ず。')],
 quote=['「音楽には色がある。ずっとあった。','私たちが忘れていただけだ。」'], foot='全14章 · 完全版はアプリで。単品でも、Pro と Pro AI にも含まれます')
